sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // 1. 使用正确的变量名reqItem（之前写成了regItem）
    var reqItem = new GlideRecord('x_1770592_easy_t_0_my_asset_request');

    // 2. 查询当前记录
    reqItem.addQuery('number', current.number);
    reqItem.query();

    if (reqItem.next()) {
        // 3. 将提交人添加到关注列表
        // 注意：watch_list字段需要用户sys_id（不是用户名），且用逗号分隔
        var currentWatchList = reqItem.watch_list || ''; // 获取当前关注列表
        var userSysId = current.opened_by.toString(); // 获取用户的sys_id

        // 4. 检查是否已在关注列表中，避免重复添加
        if (currentWatchList.indexOf(userSysId) === -1) {
            if (currentWatchList) {
                currentWatchList += ',' + userSysId; // 已有列表则追加
            } else {
                currentWatchList = userSysId; // 空列表则直接赋值
            }
            reqItem.watch_list = currentWatchList;
            reqItem.update();

            // 调试信息（可选）
            gs.info('已将用户 ' + userSysId + ' 添加到申请单 ' + current.number + ' 的关注列表');
        }
    }
})(current, previous);
